// Compile-time validation of the generated header.
//
// game_types.h is generated by URTypeRefGen from the game's dummy assemblies.
// This TU includes it with URTYPEGEN_SELF_CHECK so every generated accessor is
// instantiated during a normal build: a bad member name, an unsupported type
// mapping or a template mistake fails the build instead of the game session.
//
// Safe to delete; it contributes no runtime code.

#define URTYPEGEN_SELF_CHECK 1
#include "game_types.h"
